'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['resizeTextRuns']);
const { resizeTextRuns } = api;

const runs = [
  { text: ' hello ', pointSize: 8 },
  { text: '', pointSize: -10 },
  { text: '世界', pointSize: 500.5 }
];
const before = runs.map((run) => ({ ...run }));
const resized = resizeTextRuns(runs, 12.5);
assert.deepStrictEqual(resized, [
  { text: ' hello ', pointSize: 12.5 },
  { text: '', pointSize: 12.5 },
  { text: '世界', pointSize: 12.5 }
]);
assert.deepStrictEqual(runs, before);
assert.notStrictEqual(resized, runs);
for (let index = 0; index < runs.length; index += 1) {
  assert.notStrictEqual(resized[index], runs[index]);
}
resized[0].text = 'changed';
assert.strictEqual(runs[0].text, ' hello ');
assert.deepStrictEqual(resizeTextRuns([], 1), []);
assert.deepStrictEqual(resizeTextRuns([{ text: 'x', pointSize: 1 }], 500), [
  { text: 'x', pointSize: 500 }
]);

for (const runsValue of [null, {}, 'runs']) {
  assert.throws(() => resizeTextRuns(runsValue, 10), TypeError);
}
for (const target of [undefined, '10', NaN, Infinity, -Infinity]) {
  assert.throws(() => resizeTextRuns([], target), TypeError);
}
for (const target of [0, -1, 500.0001, 501]) {
  assert.throws(() => resizeTextRuns([], target), RangeError);
}
for (const invalidRun of [
  null,
  [],
  { text: 1, pointSize: 10 },
  { text: 'x', pointSize: '10' },
  { text: 'x', pointSize: NaN },
  { text: 'x', pointSize: Infinity }
]) assert.throws(() => resizeTextRuns([invalidRun], 10), TypeError);

